custom_css:
.yaycheckout-editorial-fashion a:hover {
	color: #d9472f;
}

.yaycheckout-editorial-fashion .wp-block-columns {
	align-items: stretch;
}

.yaycheckout-editorial-fashion .wp-block-columns > .wp-block-column.yaycheckout-editorial-fashion-bag[style*="flex-basis"] {
	flex-grow: 1;
	flex-shrink: 1;
	max-width: 560px;
	min-height: 100vh;
	box-sizing: border-box;
}

.yaycheckout-editorial-fashion-bag-inner {
	display: flex;
	flex-direction: column;
	min-height: calc(100vh - 80px);
	box-sizing: border-box;
}

.yaycheckout-editorial-fashion-bag-inner,
.yaycheckout-editorial-fashion-bag-inner > * {
	width: 100%;
	max-width: none !important;
}

.yaycheckout-editorial-fashion-bag-inner > .yaycheckout-editorial-fashion-coupon,
.yaycheckout-editorial-fashion-bag-inner > .wp-block-yaycheckout-coupon-form {
	margin-top: auto;
}

.yaycheckout-editorial-fashion-bag .yaycheckout-coupon-form__row {
	width: 100%;
}

.yaycheckout-editorial-fashion-bag .yaycheckout-coupon-form__code {
	height: 44px;
	min-height: 44px;
	padding: 0 12px;
	border: 1px solid rgba(255, 255, 255, 0.6);
	border-radius: 0;
	background: transparent;
	color: #fff;
	box-shadow: none;
}

.yaycheckout-editorial-fashion-bag .yaycheckout-coupon-form__code::placeholder {
	color: rgba(255, 255, 255, 0.7);
}

.yaycheckout-editorial-fashion-bag .yaycheckout-coupon-form__code:focus {
	border-color: #fff;
	outline: none;
	box-shadow: none;
}

.yaycheckout-editorial-fashion-bag .yaycheckout-coupon-form__apply {
	height: 44px;
	border-radius: 0;
}

.yaycheckout-editorial-fashion .yaycheckout-place-order {
	display: flex;
	align-items: center;
	justify-content: space-between;
	height: 56px;
	padding-inline: 24px;
	box-sizing: border-box;
	white-space: nowrap;
}
